"""Independent validator: replays traces, checks reply shapes, certificates, plans."""
import sys, json, random, itertools, subprocess
sys.path.insert(0,'/workspace/submission')
from compiler import verify_plan

IDOK=set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_.-")
def okid(s): return isinstance(s,str) and 1<=len(s)<=32 and all(c in IDOK for c in s)
FIELDS={
 'about':{'status','protocol'},
 'ok_load':{'status','rev','now'},
 'err':{'status','code','rev'},
 'stale':{'status','rev'},
 'audit':{'status','rev','now','leases','samples'},
 'advance':{'status','rev','now','expired'},
 'blocked':{'status','rev','link','time','used','capacity'},
 'edit_ok':{'status','rev','cancelled'},
 'replay':{'status','id','rev','base_rev','outcome'},
 'prepared':{'status','id','rev','plan'},
 'denied_cap':{'status','id','rev','kind','link','time','used','capacity'},
 'denied_cut':{'status','id','rev','kind','cut'},
 'commit':{'status','id','rev','replay'},
 'cancel':{'status','rev','released'},
 'invalid':{'status'},
}

def used(l,t,leases):
    tot=0
    for r in leases.values():
        if r['state']=='live' and r['s']<=t<r['e']:
            tot += r['env'].get(l,0)
    return tot

def check_plan(plan, n, linkuv, cap, participants, demand):
    return verify_plan(plan, n, linkuv, cap, participants, demand)

def run_trace(cmds):
    inp="\n".join(json.dumps(c) for c in cmds)+"\n"
    out=subprocess.run([sys.executable,"-I","-B","submission/main.py"],input=inp,capture_output=True,text=True)
    return [json.loads(x) for x in out.stdout.splitlines()]

def validate(cmds, replies, problems):
    st={'loaded':False,'n':0,'linkuv':[],'cap':[],'rev':0,'now':0,'leases':{},'loadids':set(),'prep':{}}
    if len(replies)!=len(cmds):
        problems.append(f"reply count {len(replies)} != {len(cmds)}"); return
    for i,(c,r) in enumerate(zip(cmds, replies)):
        op=c.get('op')
        shape=None
        if not isinstance(r,dict): problems.append(f"[{i}] reply not object"); continue
        ks=set(r.keys())
        if r.get('status')=='invalid': shape='invalid'
        elif r.get('status')=='ok' and op=='about': shape='about'
        elif r.get('status')=='ok' and op=='load': shape='ok_load'
        elif r.get('status')=='ok' and op=='audit': shape='audit'
        elif r.get('status')=='ok' and op=='advance': shape='advance'
        elif r.get('status')=='ok' and op=='edit': shape='edit_ok'
        elif r.get('status')=='ok' and op=='commit': shape='commit'
        elif r.get('status')=='ok' and op=='cancel': shape='cancel'
        elif r.get('status')=='error': shape='err'
        elif r.get('status')=='stale': shape='stale'
        elif r.get('status')=='blocked': shape='blocked'
        elif r.get('status')=='replay': shape='replay'
        elif r.get('status')=='prepared': shape='prepared'
        elif r.get('status')=='denied': shape='denied_cap' if r.get('kind')=='capacity' else 'denied_cut'
        if shape is None:
            problems.append(f"[{i}] unknown reply shape {r}"); continue
        if ks != FIELDS[shape]:
            problems.append(f"[{i}] field set {ks} != {FIELDS[shape]} for {r}"); continue
        # semantics
        if shape=='invalid':
            continue
        if shape=='about':
            if r['protocol']!='forest-controller/3': problems.append(f"[{i}] bad protocol")
            continue
        if not st['loaded']:
            if shape in ('audit','advance','edit_ok','err','stale','blocked','prepared','denied_cap','denied_cut','replay','commit','cancel'):
                if not (shape=='err' and r.get('code')=='NOT_LOADED' and r['rev']==0):
                    problems.append(f"[{i}] expected NOT_LOADED, got {r}")
            continue
        R=st['rev']; T=st['now']
        if shape=='err':
            if r['rev']!=R: problems.append(f"[{i}] err rev {r['rev']} != {R}")
            continue
        if shape=='stale':
            if r['rev']!=R: problems.append(f"[{i}] stale rev")
            continue
        if shape=='blocked':
            if r['rev']!=R: problems.append(f"[{i}] blocked rev")
            l,t,u,c=r['link'],r['time'],r['used'],r['capacity']
            if not (T<=t) or used(l,t,st['leases'])<=c or u<=c:
                problems.append(f"[{i}] blocked witness invalid: used(l,t)={used(l,t,st['leases'])} claimed {u} cap {c}")
            continue
        if shape=='audit':
            if r['rev']!=R or r['now']!=T: problems.append(f"[{i}] audit rev/now")
            live=sorted(k for k,v in st['leases'].items() if v['state']=='live')
            if r['leases']!=live: problems.append(f"[{i}] leases {r['leases']} != {live}")
            for (t,row) in r['samples']:
                exp=[st['cap'][l]-used(l,t,st['leases']) for l in range(len(st['cap']))]
                if row!=exp: problems.append(f"[{i}] sample t={t} {row} != {exp}")
            continue
        if shape=='advance':
            t=c['time']
            if r['now']!=t or r['rev']!=R+1: problems.append(f"[{i}] advance rev/now")
            exp=sorted(k for k,v in st['leases'].items() if v['state']=='live' and v['e']<=t)
            if r['expired']!=exp: problems.append(f"[{i}] expired {r['expired']} != {exp}")
            for k in exp: st['leases'][k]['state']='expired'
            st['now']=t; st['rev']=R+1
            continue
        if shape=='edit_ok':
            if r['rev']!=R+1: problems.append(f"[{i}] edit rev")
            ch={l:c2 for l,c2 in c['changes']}
            newcap=list(st['cap'])
            for l,c2 in ch.items(): newcap[l]=c2
            if c['force']:
                exp=[]
                for k,v in st['leases'].items():
                    if v['state']!='live': continue
                    if any(rate>0 and newcap[l]<st['cap'][l] for l,rate in v['env'].items()):
                        v['state']='revoked'; exp.append(k)
                if r['cancelled']!=sorted(exp): problems.append(f"[{i}] force cancelled {r['cancelled']} != {sorted(exp)}")
            else:
                if r['cancelled']!=[]: problems.append(f"[{i}] nonforce cancelled not empty")
                # must not be blocking
                blk=None
                cand={T}
                for v in st['leases'].values():
                    if v['state']=='live':
                        if v['s']>T: cand.add(v['s'])
                        if v['e']>T: cand.add(v['e'])
                for l in range(len(newcap)):
                    if newcap[l]>=st['cap'][l]: continue
                    for t in sorted(cand):
                        if used(l,t,st['leases'])>newcap[l]: blk=(l,t)
                if blk is not None: problems.append(f"[{i}] edit should have been blocked at {blk}")
            st['cap']=newcap; st['rev']=R+1
            continue
        if shape=='commit':
            if r['rev']!=R+1: problems.append(f"[{i}] commit rev")
            p=st['prep'].get(c['id'])
            if p is None: problems.append(f"[{i}] commit installed unknown")
            else:
                st['leases'][c['id']]={'owner':p['owner'],'s':p['s'],'e':p['e'],'env':dict(p['env']),'state':'live'}
            st['rev']=R+1
            continue
        if shape=='cancel':
            if r['rev']!=R+1: problems.append(f"[{i}] cancel rev")
            if c['id'] not in st['leases']: problems.append(f"[{i}] cancel unknown id")
            else: st['leases'][c['id']]['state']='cancelled'
            st['rev']=R+1
            continue
        if shape in ('prepared','denied_cap','denied_cut','replay'):
            # prepare replies: rev must be R
            if shape=='replay':
                if r['rev']!=R: problems.append(f"[{i}] replay rev")
                p=st['prep'].get(c['id'])
                if p is not None and r['outcome']!=p['outcome']:
                    problems.append(f"[{i}] replay outcome {r['outcome']} != {p['outcome']}")
                continue
            if r['rev']!=R: problems.append(f"[{i}] prepare rev {r['rev']} != {R}")
            env={l:b for l,b in c['envelope']}
            per=c['period']; s,e=c['window']
            parts={v:d for v,d in c['participants']}
            demand=dict(parts)
            if shape=='denied_cap':
                l,t,u,cc=r['link'],r['time'],r['used'],r['capacity']
                if not (s<=t<e): problems.append(f"[{i}] cap witness t outside window")
                if used(l,t,st['leases'])+env[l] <= st['cap'][l]:
                    problems.append(f"[{i}] cap witness invalid: used {used(l,t,st['leases'])}+{env[l]} <= cap {st['cap'][l]}")
                if u != used(l,t,st['leases'])+env[l] or cc != st['cap'][l]:
                    problems.append(f"[{i}] cap witness fields wrong")
                st['prep'][c['id']]={'owner':c['owner'],'s':s,'e':e,'env':env,'outcome':'denied'}
                continue
            if shape=='denied_cut':
                S=r['cut']
                if len(set(S))!=len(S): problems.append(f"[{i}] cut not distinct")
                sset=set(S)
                ins=[v for v in parts if v in sset]; outs=[v for v in parts if v not in sset]
                if not ins or not outs: problems.append(f"[{i}] cut participant sides wrong")
                capsum=sum(st['cap'][l]*0 for l in range(0))
                # cut uses p*b_l
                capsum=sum(per*env.get(l,0) for l,(u,v) in enumerate(st['linkuv']) if (u in sset)!=(v in sset))
                rsum=sum(parts[v] for v in ins)
                if capsum >= rsum: problems.append(f"[{i}] cut not deficient: {capsum} >= {rsum}")
                st['prep'][c['id']]={'owner':c['owner'],'s':s,'e':e,'env':env,'outcome':'denied'}
                continue
            if shape=='prepared':
                cap=[per*env.get(l,0) for l in range(len(st['linkuv']))]
                if not check_plan(r['plan'], st['n'], st['linkuv'], cap, sorted(parts), demand):
                    problems.append(f"[{i}] PLAN INVALID")
                st['prep'][c['id']]={'owner':c['owner'],'s':s,'e':e,'env':env,'outcome':'prepared'}
                continue
    return

def gen_trace(seed):
    rng=random.Random(seed)
    cmds=[]
    n=rng.randint(3,6)
    nl=rng.randint(1,6)
    pairs=rng.sample(list(itertools.combinations(range(n),2)), nl)
    links=[[u,v,rng.choice([1,2,3,5,8])] for (u,v) in pairs]
    parts_all=list(range(n))
    nb=rng.randint(0,2)
    bookings=[]
    usedset=set()
    for i in range(nb):
        bid=f"b{i}"
        u,v=rng.choice(links)[0], rng.choice(links)[1]
        w=(rng.randint(0,20), 0)
        env=[[l,rng.randint(1,2)] for l in rng.sample(range(len(links)), rng.randint(0,min(2,len(links))))]
        bookings.append({"id":bid,"owner":f"o{i}","window":[0,50],"envelope":env})
    cmds.append({"op":"load","n":n,"links":links,"bookings":bookings})
    for step in range(rng.randint(3,10)):
        k=rng.randint(0,6)
        choice=rng.random()
        if choice<0.15:
            cmds.append({"op":"about"})
        elif choice<0.3:
            at=sorted([rng.randint(0,60) for _ in range(rng.randint(0,3))])
            cmds.append({"op":"audit","at":at})
        elif choice<0.42:
            cmds.append({"op":"advance","time":rng.randint(0,60)})
        elif choice<0.52:
            ch=[]
            for l in rng.sample(range(len(links)), rng.randint(0,2)):
                ch.append([l, rng.randint(0,8)])
            cmds.append({"op":"edit","rev":rng.randint(0,5),"changes":ch,"force":rng.random()<0.4})
        elif choice<0.8:
            k=rng.randint(2,4)
            pv=rng.sample(range(n),k)
            participants=[[v,rng.choice([0,1,2,3])] for v in pv]
            if sum(d for _,d in participants)==0: participants[0][1]=1
            env=[[l,rng.randint(1,3)] for l in rng.sample(range(len(links)), rng.randint(1,len(links)))]
            s=rng.randint(0,40); p=rng.choice([1,2,5,10])
            cmds.append({"op":"prepare","id":f"pp{rng.randint(0,1)}","owner":f"o{rng.randint(0,2)}",
                         "window":[s,s+p*rng.randint(1,3)],"period":p,"participants":participants,
                         "envelope":env,"rev":rng.randint(0,6)})
        elif choice<0.92:
            cmds.append({"op":"commit","id":f"pp{rng.randint(0,1)}","owner":f"o{rng.randint(0,2)}","rev":rng.randint(0,6)})
        else:
            cmds.append({"op":"cancel","id":f"pp{rng.randint(0,1)}","owner":f"o{rng.randint(0,2)}","rev":rng.randint(0,6)})
    return cmds

def main():
    seed0=int(sys.argv[1]); N=int(sys.argv[2])
    bad=0
    for seed in range(seed0, seed0+N):
        cmds=gen_trace(seed)
        replies=run_trace(cmds)
        problems=[]
        validate(cmds, replies, problems)
        if problems:
            bad+=1
            print("SEED",seed,"PROBLEMS:")
            for p in problems[:6]: print("   ",p)
            print("   cmds:", json.dumps(cmds)[:1200])
    print("traces",N,"bad",bad)

main()
